import React, { useState, useEffect, useRef } from 'react';
import AuraCanvas from '../components/AuraCanvas';

const PHASES = [
  { name:'Andas in',  seconds:4,  hues:[195,215], intensity:0.55, speed:0.15, label:'Djupt in genom näsan' },
  { name:'Håll',      seconds:7,  hues:[210,228], intensity:0.45, speed:0.06, label:'Håll andan stilla' },
  { name:'Andas ut',  seconds:8,  hues:[175,195], intensity:0.5,  speed:0.18, label:'Sakta ut genom munnen' },
];
const TOTAL = 4;

export default function Breathing({ setPage }) {
  const [running,  setRunning]  = useState(false);
  const [done,     setDone]     = useState(false);
  const [phase,    setPhase]    = useState(0);
  const [count,    setCount]    = useState(0);
  const [cycle,    setCycle]    = useState(0);
  const timer = useRef(null);

  const runPhase = (pi, ci) => {
    if (ci >= TOTAL) { setRunning(false); setDone(true); return; }
    setPhase(pi); setCycle(ci); setCount(PHASES[pi].seconds);
    let c = PHASES[pi].seconds;
    timer.current = setInterval(() => {
      c--; setCount(c);
      if (c <= 0) { clearInterval(timer.current); const np = (pi+1)%3; setTimeout(() => runPhase(np, np===0?ci+1:ci), 400); }
    }, 1000);
  };
  const start = () => { setRunning(true); setDone(false); runPhase(0, 0); };
  useEffect(() => () => clearInterval(timer.current), []);
  const cur = PHASES[phase];

  // Circle size: inhale grows, hold stays, exhale shrinks
  const circleScale = running
    ? phase === 0 ? 1.45
    : phase === 1 ? 1.45
    : 0.72
    : 1.0;

  const circleDuration = running
    ? phase === 0 ? `${PHASES[0].seconds}s`
    : phase === 1 ? '0.6s'
    : `${PHASES[2].seconds}s`
    : '1.2s';

  const circleEasing = running
    ? phase === 0 ? 'linear'
    : phase === 1 ? 'ease'
    : 'linear'
    : 'cubic-bezier(0.16,1,0.3,1)';

  if (done) return (
    <div style={{ position:'relative', height:'100vh', overflow:'hidden', background:'#0a0a0a' }}>
      <AuraCanvas hues={[155,175]} intensity={0.55} speed={0.45} />
      <div style={{ position:'absolute', inset:0, zIndex:10, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', textAlign:'center', padding:'0 32px' }}>
        <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.22em', textTransform:'uppercase', color:'rgba(240,237,230,0.35)', marginBottom:16 }}>{TOTAL} omgångar · klart</p>
        <h2 style={{ fontFamily:'Syne,sans-serif', fontSize:'clamp(32px,8vw,50px)', fontWeight:800, letterSpacing:'-0.04em', color:'#f0ede6', marginBottom:10 }}>Bra jobbat</h2>
        <p style={{ fontSize:14, color:'rgba(240,237,230,0.4)', marginBottom:36, fontWeight:300, maxWidth:240 }}>Ditt nervsystem har lugnat ner sig.</p>
        <div style={{ display:'flex', gap:10 }}>
          <button onClick={()=>setPage('checkin')} style={{ padding:'13px 24px', borderRadius:100, background:'rgba(240,237,230,0.9)', color:'#0a0a0a', fontSize:13, fontWeight:700, border:'none' }}>Check-in →</button>
          <button onClick={()=>{setDone(false);setRunning(false);}} style={{ padding:'13px 24px', borderRadius:100, background:'rgba(255,255,255,0.07)', border:'1px solid rgba(255,255,255,0.12)', color:'rgba(240,237,230,0.55)', fontSize:13 }}>Igen</button>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ position:'relative', height:'100vh', overflow:'hidden', background:'#0a0a0a' }}>
      <AuraCanvas hues={running ? cur.hues : [195,215]} intensity={running ? cur.intensity : 0.4} speed={running ? cur.speed : 0.22} />

      <div style={{ position:'absolute', inset:0, zIndex:10, display:'flex', flexDirection:'column', padding:'28px 22px', paddingBottom:100 }}>

        {/* Phase numbers — top centre */}
        <div style={{ textAlign:'center', marginBottom:'auto' }}>
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.22em', textTransform:'uppercase', color:'rgba(240,237,230,0.25)', marginBottom:18 }}>4 – 7 – 8</p>
          <div style={{ display:'flex', gap:24, justifyContent:'center' }}>
            {PHASES.map((p, i) => (
              <div key={i}>
                <div style={{ fontFamily:'Syne,sans-serif', fontSize:22, fontWeight:700, letterSpacing:'-0.03em', lineHeight:1, color:running&&phase===i?'rgba(240,237,230,0.9)':'rgba(240,237,230,0.18)', transition:'color .5s' }}>{p.seconds}</div>
                <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, textTransform:'uppercase', letterSpacing:'0.1em', color:running&&phase===i?'rgba(240,237,230,0.5)':'rgba(240,237,230,0.15)', marginTop:3, transition:'color .5s' }}>{p.name}</div>
              </div>
            ))}
          </div>
        </div>

        {/* THE CIRCLE — the main breathing object */}
        <div style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center' }}>
          <div style={{ position:'relative' }}>
            {/* Outer glow ring — expands more dramatically */}
            <div style={{
              position:'absolute',
              inset: running && phase <= 1 ? '-40px' : '-8px',
              borderRadius:'50%',
              background: running
                ? `radial-gradient(circle, hsla(${cur.hues[0]+20},55%,60%,0.15) 0%, transparent 70%)`
                : 'radial-gradient(circle, rgba(200,195,220,0.08) 0%, transparent 70%)',
              transition:`inset ${circleDuration} ${circleEasing}, background 1s ease`,
              filter:'blur(12px)',
            }} />

            {/* Main circle */}
            <div style={{
              width: 200,
              height: 200,
              borderRadius: '50%',
              transform: `scale(${circleScale})`,
              transition: `transform ${circleDuration} ${circleEasing}`,
              position: 'relative',
              background: running
                ? `radial-gradient(circle at 38% 35%, hsla(${cur.hues[0]+30},60%,72%,0.95) 0%, hsla(${cur.hues[0]},52%,52%,0.9) 40%, hsla(${cur.hues[1]},45%,38%,0.85) 100%)`
                : 'radial-gradient(circle at 38% 35%, rgba(210,208,225,0.85) 0%, rgba(165,162,195,0.75) 45%, rgba(100,98,140,0.65) 100%)',
              boxShadow: running
                ? `0 0 60px hsla(${cur.hues[0]},55%,50%,0.4), 0 0 120px hsla(${cur.hues[0]},50%,45%,0.2), inset 0 2px 0 rgba(255,255,255,0.25)`
                : '0 0 40px rgba(160,158,200,0.2), inset 0 2px 0 rgba(255,255,255,0.15)',
              transition: `transform ${circleDuration} ${circleEasing}, background 1s ease, box-shadow 1s ease`,
            }}>
              {/* Inner specular highlight */}
              <div style={{ position:'absolute', top:'18%', left:'22%', width:'35%', height:'28%', borderRadius:'50%', background:'rgba(255,255,255,0.22)', filter:'blur(8px)' }} />

              {/* Count inside */}
              {running && (
                <div style={{ position:'absolute', inset:0, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center' }}>
                  <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.14em', textTransform:'uppercase', color:'rgba(255,255,255,0.55)', marginBottom:3 }}>{cur.name}</div>
                  <div style={{ fontFamily:'Syne,sans-serif', fontSize:52, fontWeight:700, color:'rgba(255,255,255,0.88)', lineHeight:1, letterSpacing:'-0.04em' }}>{count}</div>
                  <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, color:'rgba(255,255,255,0.35)', marginTop:4 }}>{cycle+1} / {TOTAL}</div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Bottom */}
        <div>
          {running ? (
            <div style={{ background:'rgba(10,10,10,0.7)', backdropFilter:'blur(20px)', borderRadius:18, padding:'12px 18px', textAlign:'center', border:'1px solid rgba(255,255,255,0.06)' }}>
              <p style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.14em', textTransform:'uppercase', color:'rgba(240,237,230,0.4)' }}>{cur.label}</p>
            </div>
          ) : (
            <>
              <h1 style={{ fontFamily:'Syne,sans-serif', fontSize:'clamp(28px,7vw,42px)', fontWeight:800, letterSpacing:'-0.04em', color:'#f0ede6', marginBottom:8, lineHeight:1 }}>Andningsövning</h1>
              <p style={{ fontSize:13, color:'rgba(240,237,230,0.4)', fontWeight:300, lineHeight:1.75, marginBottom:20 }}>
                Aktiverar det parasympatiska nervsystemet. 4 minuter.
              </p>
              <button onClick={start} style={{ width:'100%', padding:'15px', borderRadius:100, background:'rgba(240,237,230,0.9)', color:'#0a0a0a', fontSize:14, fontWeight:700, border:'none', boxShadow:'0 8px 40px rgba(0,0,0,0.5)', fontFamily:'Syne,sans-serif' }}>
                Starta →
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
